import io


_ORDER_REQUIRED = ("order_id", "customer", "amount", "status")
_REFUND_REQUIRED = ("refund_id", "order_id", "amount")


def _read_table(text, required_columns, label):
    """Read a UTF-8 CSV string without mutating the caller's data."""
    if not isinstance(text, str):
        raise ValueError("%s CSV must be a string" % label)

    try:
        raw_rows = list(csv.reader(io.StringIO(text, newline="")))
    except csv.Error as exc:
        raise ValueError("invalid %s CSV: %s" % (label, exc))

    # Ignore leading blank lines before the header.
    while raw_rows and (not raw_rows[0] or all(cell == "" for cell in raw_rows[0])):
        raw_rows.pop(0)

    if not raw_rows:
        raise ValueError("%s CSV is missing its header" % label)

    header = list(raw_rows[0])
    if header:
        header[0] = header[0].lstrip("\ufeff")
    header = [name.strip() for name in header]

    if any(name == "" for name in header):
        raise ValueError("%s CSV has a blank column name" % label)
    if len(set(header)) != len(header):
        raise ValueError("%s CSV has duplicate column names" % label)

    missing = [name for name in required_columns if name not in header]
    if missing:
        raise ValueError(
            "%s CSV is missing required column(s): %s"
            % (label, ", ".join(missing))
        )

    width = len(header)
    records = []
    for line_number, row in enumerate(raw_rows[1:], start=2):
        if len(row) == 0:
            continue
        if len(row) != width:
            raise ValueError(
                "%s CSV row %d has %d field(s), expected %d"
                % (label, line_number, len(row), width)
            )
        records.append((tuple(row), {header[i]: row[i] for i in range(width)}))

    return records


